/* بيانات باب bir: تُحمَّل عند أول فتح للقسم */
window.BIR = {"ch":[{"id":"jami","t":"حقيقة البر وجامع آيته","d":"الآيات التي تبيّن ما هو البر وما ليس منه: آية البقرة الجامعة، والإنفاق مما يُحب، والتقوى أصل البر، وذمّ من يأمر بالبر وينسى نفسه، وورود «البر» اسماً لله تعالى."},{"id":"walid","t":"بر الوالدين","d":"الآيات التي قرنت الإحسان إلى الوالدين بالتوحيد، وما ذكره القرآن من برّ الأنبياء بوالديهم، وبقاء الصحبة بالمعروف وإن جاهدا على الشرك."},{"id":"duafa","t":"البر بالأقارب واليتامى والمساكين","d":"الآيات التي جعلت من البر الإنفاق على ذوي القربى واليتامى والمساكين وابن السبيل، وإكرام اليتيم، وفك الرقاب، وذمّ من يدعّ اليتيم ولا يحضّ على طعام المسكين."},{"id":"tawun","t":"التعاون على البر وبرّ الناس","d":"الآيات التي أمرت بالتعاون على البر والتقوى والتناجي بهما، والإصلاح بين الناس، والعدل والإحسان، وبرّ غير المحاربين من غير المسلمين."},{"id":"abrar","t":"الأبرار وجزاؤهم","d":"الآيات التي وصفت الأبرار وكتابهم ونعيمهم، ودعاء المؤمنين أن يُتوفوا مع الأبرار، ووصف الملائكة بالبررة."}],"tp":[{"id":"jami","ch":"jami","t":"«ليس البر أن تولوا وجوهكم»: الآية الجامعة","e":"وصف البر بإيمان القلب وأعمال الجوارح وصدق الخلق مجتمعةً، وأنه ليس مجرد توجّه الوجوه.","ay":[[2,177,177]],"q":[{"bk":"saadi","s":2,"ay":177,"x":"يقول تعالى: {ليس البر أن تولوا وجوهكم قبل المشرق والمغرب}؛ أي: ليس هذا هو البر المقصود من العباد فيكون كثرة البحث فيه والجدال من العناء الذي ليس تحته إلا الشقاق والخلاف، وهذا نظير قوله - صلى الله عليه وسلم -: «ليس الشديد بالصرعة إنما الشديد الذي يملك نفسه عند الغضب» ، ونحو ذلك، {ولكن البر من آمن بالله}؛ أي: بأنه إله واحد موصوف بكل صفة كمال منزَّه عن كلِّ نقص {واليوم الآخر}؛ وهو كل ما أخبر الله به في كتابه أو أخبر به الرسول مما يكون بعد الموت {والملائكة}؛ الذين وصفهم الله لنا في كتابه ووصفهم رسوله - صلى الله عليه وسلم -، {والكتاب}؛ أي: جنس الكتب التي أنزلها الله على رسله وأعظمها القرآن فيؤمن بما تضمنه من الأخبار والأحكام.","w":"السعدي","en":"Al-Sa'di: 'It is not righteousness that you turn your faces toward east or west' means that this is not the righteousness meant for people, so that endless debate over it would be wasted effort that leads only to division, like the saying of the Prophet that the strong one is the one who controls himself in anger; 'but righteousness is whoever believes in Allah' means that He is one God, described with every attribute of perfection and free of every defect, and in the Last Day, the angels, and the Book, meaning all the books Allah sent down, the greatest being the Quran."},{"bk":"saadi","s":2,"ay":177,"x":"أي: المتصفون بما ذكر من العقائد الحسنة والأعمال التي هي آثار الإيمان وبرهانه ونوره والأخلاق التي هي جمال الإنسان وحقيقة الإنسانية فأولئك {الذين صدقوا}؛ في إيمانهم لأن أعمالهم صدقت إيمانهم {وأولئك هم المتقون}؛ لأنهم تركوا المحظور وفعلوا المأمور، لأن هذه الأمور مشتملة على كل خصال الخير تضمناً ولزوماً لأن الوفاء بالعهد يدخل فيه الدين كله، ولأن العبادات المنصوص عليها في هذه الآية أكبر العبادات، ومن قام بها كان بما سواها أقوم، فهؤلاء [هم] الأبرار الصادقون المتقون.","w":"السعدي","en":"Al-Sa'di: 'Those' are the ones described with these good beliefs, with the deeds that are the traces and proof of faith, and with the character that is the beauty of a human being; they are 'the truthful' in their faith, because their deeds confirmed it, and 'they are the godfearing', because they left what is forbidden and did what is commanded. These matters contain every good trait, since fulfilling covenants includes the whole religion and the acts of worship named in the verse are the greatest; whoever keeps them will keep everything else better. These are the abrar, the truthful, the godfearing."},{"bk":"ibnkathir","s":2,"ay":177,"x":"وَقَالَ الْعَوْفِيُّ عَنِ ابْنِ عَبَّاسٍ فِي هَذِهِ الْآيَةِ: لَيْسَ الْبَرَّ أَنْ تُصَلُّوا وَلَا تَعْمَلُوا.","w":"ابن كثير","en":"Ibn Kathir: al-'Awfi reported from Ibn 'Abbas on this verse: righteousness is not that you pray and do not act."}]},{"id":"hatta","ch":"jami","t":"«لن تنالوا البر حتى تنفقوا مما تحبون»","e":"أن بلوغ البر مرتبط بالإنفاق مما يحبه الإنسان.","ay":[[3,92,92]],"q":[{"bk":"saadi","s":3,"ay":92,"x":"يعني {لن تنالوا} وتدركوا {البر}، الذي هو اسم جامع للخيرات وهو: الطريق الموصل إلى الجنة {حتى تنفقوا مما تحبون} من أطيب أموالكم وأزكاها، فإن النفقة من الطيب المحبوب للنفوس من أكبر الأدلة على سماحة النفس واتصافها بمكارم الأخلاق ورحمتها ورقتها، ومن أدل الدلائل على محبة الله وتقديم محبته على محبة الأموال التي جبلت النفوس على قوة التعلق بها، فمن آثر محبة الله على محبة نفسه فقد بلغ الذروة العليا من الكمال وكذلك من أنفق الطيبات وأحسن إلى عباد الله أحسن الله إليه ووفقه أعمالاً وأخلاقاً لا تحصل بدون هذه الحالة.","w":"السعدي","en":"Al-Sa'di: 'You will never attain birr', which is a comprehensive word for all good things and the road that leads to Paradise, 'until you spend from what you love', from the best and purest of your wealth. Spending from the good things the soul loves is among the greatest proofs of a generous self, good character, mercy and tenderness, and of putting love of Allah before love of wealth, to which souls are naturally attached. Whoever puts love of Allah before his own love has reached the highest peak of perfection; and whoever spends good things and does good to Allah's servants, Allah does good to him and grants him deeds and character he could not reach otherwise."},{"bk":"saadi","s":3,"ay":92,"x":"وأيضاً فمن قام بهذه النفقة على هذا الوجه كان قيامه ببقية الأعمال الصالحة والأخلاق الفاضلة من طريق الأولى والأحرى، ومع أن النفقة من الطيبات هي أكمل الحالات فمهما أنفق العبد من نفقة قليلة أو كثيرة من طيب أو غيره {فإن الله به عليم}، وسيجزي كل منفق بحسب عمله، سيجزيه في الدنيا بالخلف العاجل وفي الآخرة بالنعيم الآجل.","w":"السعدي","en":"Al-Sa'di: whoever spends in this way will all the more readily keep up the other righteous deeds and noble character. Yet whatever a servant spends, little or much, good or otherwise, 'Allah is aware of it', and will repay each spender according to his deed: in this world with a swift replacement and in the Hereafter with lasting delight."}]},{"id":"buyut","ch":"jami","t":"«وليس البر بأن تأتوا البيوت من ظهورها»","e":"أن البر ليس في عادة يظنها المرء قربة بلا شرع، وأن حقيقته التقوى.","ay":[[2,189,189]],"q":[{"bk":"saadi","s":2,"ay":189,"x":"وهذا كما كان الأنصار وغيرهم من العرب إذا أحرموا لم يدخلوا البيوت من أبوابها؛ تعبداً بذلك وظنًّا أنه برٌّ، فأخبر تعالى أنه ليس من البرِّ ؛ لأن الله تعالى لم يشرعه لهم، وكل من تعبد بعبادة لم يشرعها الله ولا رسوله فهو متعبد ببدعة، وأمرهم أن يأتوا البيوت من أبوابها؛ لما فيه من السهولة عليهم التي هي قاعدة من قواعد الشرع.","w":"السعدي","en":"Al-Sa'di: this is how the Ansar and other Arabs, when in ihram, would not enter houses by their doors, as an act of worship and thinking it was birr. Allah told them it is not part of birr because He never legislated it, and whoever worships with what Allah and His Messenger did not legislate is following an innovation. He told them to enter houses by their doors, because of the ease in that, which is one of the principles of the Law."},{"bk":"saadi","s":2,"ay":189,"x":"هذا هو البرُّ الذي أمر الله به، وهو لزوم تقواه على الدوام بامتثال أوامره واجتناب نواهيه، فإنه سبب للفلاح الذي هو الفوز بالمطلوب والنجاة من المرهوب، فمن لم يتق الله تعالى لم يكن له سبيل إلى الفلاح، ومن اتقاه فاز بالفلاح والنجاح.","w":"السعدي","en":"Al-Sa'di: 'this is the birr that Allah commanded': holding to taqwa always by following His commands and avoiding His prohibitions. It is the cause of success, which is attaining what is sought and being saved from what is feared; whoever does not fear Allah has no path to success, and whoever does fear Him wins success and prosperity."}]},{"id":"amr","ch":"jami","t":"«أتأمرون الناس بالبر وتنسون أنفسكم»","e":"ذمّ الأمر بالبر مع نسيان النفس عنه.","ay":[[2,44,44]],"q":[{"bk":"saadi","s":2,"ay":44,"x":"{أتأمرون الناس بالبر}؛ أي: بالإيمان والخير، {وتنسون أنفسكم}؛ أي: تتركونها عن أمرها بذلك والحال، {وأنتم تتلون الكتاب أفلا تعقلون}؛ وسُمِّي العقل عقلاً؛ لأنه يعقل به ما ينفعه من الخير، وينعقل به عما يضره، وذلك أن العقل يحث صاحبه أن يكون أول فاعل لما يأمر به، وأول تارك لما ينهى عنه، فمن أمر غيره بالخير ولم يفعله أو نهاه عن الشر فلم يتركه دل على عدم عقله وجهله، خصوصاً إذا كان عالماً بذلك، قد قامت عليه الحجة، وهذه الآية وإن كانت نزلت في سبب بني إسرائيل، فهي عامة لكل أحد لقوله تعالى:{يا أيها الذين آمنوا لم تقولون ما لا تفعلون كبر مقتاً عند الله أن تقولوا ما لا تفعلون} …","w":"السعدي","en":"Al-Sa'di: 'Do you command people to birr', meaning faith and good, 'and forget yourselves', leaving yourselves out of it, 'while you recite the Book. Will you not reason?' Reason is called 'aql because by it one holds back from what harms; it urges its owner to be the first to do what he commands and the first to leave what he forbids. Whoever commands good and does not do it, or forbids evil and does not leave it, shows a lack of reason and knowledge, especially if he knows. Although the verse came down about the Children of Israel, it applies to everyone, as in the verse 'Why do you say what you do not do? It is greatly hateful to Allah that you say what you do not do'."},{"bk":"ibnkathir","s":2,"ay":44,"x":"يَقُولُ تَعَالَى: كَيْفَ يَلِيقُ بِكُمْ -يَا مَعْشَرَ أَهْلِ الْكِتَابِ، وَأَنْتُمْ تَأْمُرُونَ النَّاسَ بِالْبِرِّ، وَهُوَ جِمَاعُ الْخَيْرِ-أَنْ تَنْسَوْا أَنْفُسَكُمْ، فَلَا تَأْتَمِرُوا بِمَا تَأْمُرُونَ النَّاسَ بِهِ، وَأَنْتُمْ مَعَ ذَلِكَ تَتْلُونَ الْكِتَابَ، وَتَعْلَمُونَ مَا فِيهِ عَلَى مَنْ قَصر فِي أَوَامِرِ اللَّهِ؟","w":"ابن كثير","en":"Ibn Kathir: Allah says: how can it suit you, People of the Book, that you command people to birr, which is the sum of all good, and forget yourselves, so that you do not follow what you command others, while you recite the Book and know what it says about whoever falls short in Allah's commands?"}]},{"id":"ism","ch":"jami","t":"«إنه هو البر الرحيم»","e":"ورود «البر» اسماً لله تعالى في آخر ما قاله أهل الجنة.","ay":[[52,26,28]],"q":[{"bk":"saadi","s":52,"ay":28,"x":"فمن برِّه [بنا] ورحمته إيَّانا أنالَنا رضاه والجنة، ووقانا سخطه والنار.","w":"السعدي","en":"Al-Sa'di: out of His birr and His mercy to us, He granted us His pleasure and Paradise and protected us from His anger and the Fire."},{"bk":"ibnkathir","s":52,"ay":28,"x":"﴿إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ﴾ أَيْ: نَتَضَرَّعُ إِلَيْهِ فَاسْتَجَابَ [اللَّهُ] لَنَا وَأَعْطَانَا سُؤْلَنَا، ﴿إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ﴾ …","w":"ابن كثير","en":"Ibn Kathir: 'We used to call upon Him before' means we used to plead to Him, and Allah answered us and gave us what we asked; 'Indeed, He is the Kind, the Merciful'."}]},{"id":"ihsan","ch":"walid","t":"«وبالوالدين إحساناً» وخفض جناح الذل","e":"قرن الإحسان إلى الوالدين بتوحيد الله، وأدب القول والتواضع لهما والدعاء.","ay":[[17,23,24]],"q":[{"bk":"saadi","s":17,"ay":23,"x":"ثم ذكر بعد حقِّه القيام بحقِّ الوالدين، فقال:{وبالوالدين إحساناً}؛ أي: أحسنوا إليهما بجميع وجوه الإحسان القوليِّ والفعليِّ؛ لأنهما سببُ وجود العبد، ولهما من المحبَّة للولد والإحسان إليه، والقرب ما يقتضي تأكُّد الحقِّ ووجوب البرِّ.","w":"السعدي","en":"Al-Sa'di: after His own right, He mentions the right of parents: 'and to parents, good treatment' means be good to them in every way, in word and in deed, because they are the cause of the servant's existence, and the love they have for the child and the good they do for him and their closeness make the right all the stronger and make dutifulness (birr) obligatory."},{"bk":"saadi","s":17,"ay":23,"x":"{واخفضۡ لهما جناحَ الذُّلِّ من الرحمةِ}؛ أي: تواضع لهما ذُلًّا لهما ورحمةً واحتساباً للأجر، لا لأجل الخوف منهما أو الرجاء لما لهما ونحو ذلك من المقاصد التي لا يؤجَر عليها العبد.","w":"السعدي","en":"Al-Sa'di: 'lower to them the wing of humility out of mercy' means be humble to them out of humility, mercy and seeking reward, not out of fear of them or hope for what they have, or other motives for which a servant earns no reward."},{"bk":"saadi","s":17,"ay":23,"x":"أي: ادعُ لهما بالرحمة أحياءً وأمواتاً؛ جزاءً على تربيتهما إيَّاك صغيراً.","w":"السعدي","en":"Al-Sa'di: 'and say: My Lord, have mercy on them' means pray for mercy for them, living and dead, in return for their having raised you when you were small."}]},{"id":"wasiyya","ch":"walid","t":"«ووصينا الإنسان بوالديه» وصحبتهما بالمعروف","e":"الوصية بالوالدين مع شكر الله، وبقاء المصاحبة بالمعروف إذا جاهدا على الشرك.","ay":[[31,14,15]],"q":[{"bk":"saadi","s":31,"ay":14,"x":"فوصيناه {بوالديه}، وقلنا له:{اشكُرۡ لي}: بالقيام بعبوديَّتي وأداء حقوقي وأنْ لا تستعينَ بنعمي على معصيتي {ولوالديك}: بالإحسان إليهما بالقول الليِّن والكلام اللطيف والفعل الجميل والتواضع لهما وإكرامهما وإجلالهما والقيام بمؤونتهما واجتناب الإساءة إليهما من كلِّ وجه بالقول والفعل، فوصيناه بهذه الوصية وأخبرناه أنَّ {إليَّ المصيرُ}؛ أي: سترجع أيُّها الإنسان إلى من وصَّاك وكلَّفك بهذه الحقوق، فيسألك: هل قمتَ بها فيثيبك الثواب الجزيل، أم ضيَّعْتها فيعاقبك العقاب الوبيل؟!","w":"السعدي","en":"Al-Sa'di: 'We enjoined him about his parents', saying: 'be grateful to Me' by worshipping Me, giving Me My due and not using My blessings to disobey Me, 'and to your parents' by treating them well in gentle speech, kind words, good deeds, humility, honouring them, looking after their needs and avoiding any harm to them in word or deed. This was the charge, and He told him that 'to Me is the return', when you will be asked whether you kept these duties and rewarded richly, or neglected them and punished severely."},{"bk":"saadi","s":31,"ay":15,"x":"{وإن جاهداك}؛ أي: اجتهد والداك {على أن تشرِكَ بي ما ليس لك به علمٌ فلا تُطِعۡهُما}: ولا تظنَّ أنَّ هذا داخل في الإحسان إليهما؛ لأنَّ حق الله مقدَّم على حقِّ كل أحدٍ، ولا طاعة لمخلوقٍ في معصية الخالق، ولم يقلْ: وإنْ جاهداك على أن تُشْرِكَ بي ما ليس لك به علمٌ؛ فعقَّهما، بل قال:{فلا تُطِعۡهُما}؛ أي: في الشرك ، وأمَّا برُّهما؛ فاستمرَّ عليه، ولهذا قال:{وصاحِبۡهُما في الدُّنيا معروفاً}؛ أي: صحبة إحسان إليهما بالمعروف، وأما اتِّباعُهما وهما بحالة الكفر والمعاصي؛ فلا تتَّبِعْهما، {واتَّبِعۡ سبيلَ مَنۡ أناب إليَّ}: وهم المؤمنون بالله وملائكته وكتبه ورسله، المستسلمون لربِّهم، المنيبون إليه، واتِّباع سبيلهم أن يَسْلُكَ مسلَكَهم في الإنابة إلى الله، التي هي انجذابُ دواعي القلب وإراداته إلى الله …","w":"السعدي","en":"Al-Sa'di: 'If they strive with you to make you associate with Me what you have no knowledge of, do not obey them': do not think that this falls under good treatment of them, since Allah's right comes before anyone's and there is no obedience to a creature in disobedience to the Creator. He did not say to be harsh with them but 'do not obey them' in shirk, while dutifulness to them continues: 'keep company with them in this world with kindness'. But do not follow them in unbelief and disobedience; 'follow the way of him who turns to Me', the believers, who submit to their Lord and turn to Him."}]},{"id":"ahqaf","ch":"walid","t":"«حملته أمه كرهاً ووضعته كرهاً»: دعاء الابن البار","e":"ما تحمّلته الأم من الحمل والوضع والإرضاع، وسبب الوصية بالإحسان إليهما.","ay":[[46,15,15]],"q":[{"bk":"saadi","s":46,"ay":15,"x":"هذا من لطفه تعالى بعباده وشكره للوالدين أن وصَّى الأولاد وعهد إليهم أن يحسنوا إلى والديهم بالقول اللطيف والكلام الليِّن وبَذْل المال والنفقة وغير ذلك من وجوه الإحسان، ثم نبَّه على ذكر السبب الموجب لذلك، فذكر ما تحمَّلته الأمُّ من ولدها، وما قاستْه من المكاره وقت حَمْلِها، ثم مشقَّة ولادتها المشقَّة الكبيرة، ثم مشقَّة الرضاع وخدمة الحضانة، وليست المذكوراتُ مدة يسيرة ساعة أو ساعتين، وإنما ذلك مدة طويلة قدرها {ثلاثون شهراً}: للحمل تسعة أشهر ونحوها، والباقي للرضاع، هذا الغالب.","w":"السعدي","en":"Al-Sa'di: this is from Allah's gentleness to His servants and His gratitude to parents, that He charged children to be good to their parents with gentle speech, kind words, spending money on them and other forms of kindness. He then points to the reason: what the mother bore for her child, the hardships of pregnancy, the great hardship of birth, then the toil of nursing and caring, which is not a short while but a long period of 'thirty months', about nine for pregnancy and the rest for nursing, as is usual."}]},{"id":"yahya","ch":"walid","t":"يحيى عليه السلام: «وبراً بوالديه ولم يكن جباراً عصياً»","e":"وصف يحيى عليه السلام بأنه برٌّ بوالديه ولم يكن جباراً عصياً.","ay":[[19,12,14]],"q":[{"bk":"saadi","s":19,"ay":14,"x":"ومن كان مؤمناً تقيًّا؛ كان لله وليًّا، وكان من أهل الجنة التي أُعدَّت للمتقين، وحصل له من الثواب الدنيويِّ والأخرويِّ ما رتَّبه الله على التَّقوى، وكان أيضاً {برًّا بوالديه}؛ أي: لم يكن عاقًّا ولا مسيئاً إلى أبويه، بل كان محسناً إليهما بالقول والفعل.","w":"السعدي","en":"Al-Sa'di: whoever is a godfearing believer is a friend of Allah and among the people of Paradise prepared for the godfearing, and gains the worldly and otherworldly reward Allah has attached to taqwa; he was also 'dutiful to his parents': never undutiful nor bad to them, but good to them in word and deed."},{"bk":"saadi","s":19,"ay":14,"x":"أي: لم يكن متجبراً متكبراً عن عبادة الله، ولا مترفِّعاً على عباد الله ولا على والديه، بل كان متواضعاً متذلِّلاً مطيعاً أوَّاباً لله على الدوام، فجمع بين القيام بحقِّ الله وحق خلقه.","w":"السعدي","en":"Al-Sa'di: he was not arrogant or proud before the worship of Allah, nor lofty toward Allah's servants or toward his parents, but humble, lowly, obedient and constantly turning to Allah, combining Allah's right and the rights of His creatures."}]},{"id":"isa","ch":"walid","t":"عيسى عليه السلام: «وبراً بوالدتي»","e":"قول عيسى عليه السلام في المهد: ﴿وبراً بوالدتي﴾.","ay":[[19,30,33]],"q":[{"bk":"saadi","s":19,"ay":32,"x":"وأوصاني أيضاً أن أبَرَّ والدتي فأحسِنَ إليها غايةَ الإحسان، وأقومَ بما ينبغي لها؛ لشرفِها وفضلِها، ولكونِها والدةً لها حقُّ الولادة وتوابعها.","w":"السعدي","en":"Al-Sa'di: He also charged me to be dutiful to my mother and to treat her with the utmost kindness and do what is due to her, because of her honour and virtue and because as a mother she has the right of giving birth and what follows from it."}]},{"id":"ayat36","ch":"duafa","t":"الإحسان إلى الأقربين واليتامى والمساكين","e":"ذكر الوالدين وذي القربى واليتامى والمساكين والجار والصاحب وابن السبيل بعد الأمر بالعبادة.","ay":[[4,36,36]],"q":[{"bk":"saadi","s":4,"ay":36,"x":"ثم بعد ما أمر بعبادتِهِ والقيام بحقِّه أمر بالقيام بحقوق العبادِ الأقرب فالأقرب، فقال:{وبالوالدين إحساناً}؛ أي: أحسنوا إليهم بالقول الكريم والخطاب اللطيف والفعل الجميل، بطاعةِ أمرِهما واجتنابِ نهيِهِما، والإنفاق عليهما، وإكرام من له تعلُّق بهما، وصلة الرحم التي لا رحمَ لك إلاَّ بهما.","w":"السعدي","en":"Al-Sa'di: after commanding worship of Him and giving Him His right, He commands the rights of people, the nearest first: 'and to parents, good treatment', meaning be good to them with gracious speech, gentle address and good deeds, by obeying their commands, avoiding their prohibitions, spending on them, honouring those connected to them and keeping the ties of kinship that exist only through them."},{"bk":"saadi","s":4,"ay":36,"x":"أي: الذين فُقِدَ آباؤهم وهم صغارٌ، فلهم حقٌّ على المسلمين، سواءٌ كانوا أقارب أو غيرهم، بكفالتهم وبِرِّهم وجبرِ خواطرِهم وتأديبِهم وتربيتهم أحسن تربية في مصالح دينهم ودنياهم.","w":"السعدي","en":"Al-Sa'di: 'and the orphans', those who lost their fathers when young, have a right over the Muslims, whether relatives or not: to be cared for, treated with birr, comforted, taught manners and brought up as well as possible in their religious and worldly interests."}]},{"id":"nafaqa","ch":"duafa","t":"«ما أنفقتم من خير فللوالدين والأقربين»","e":"ترتيب المنفَق عليهم في الإنفاق من الخير.","ay":[[2,215,215]],"q":[{"bk":"saadi","s":2,"ay":215,"x":"أي: يسألونك عن النفقة وهذا يعم السؤال عن المنفَق والمنفَق عليه، فأجابهم عنها فقال:{قل ما أنفقتم من خير}؛ أي: مال قليل أو كثير فأولى الناس به وأحقهم بالتقديم أعظمهم حقًّا عليك، وهم الوالدان الواجب برهما والمحرم عقوقهما، ومن أعظم برهما، النفقة عليهما، ومن أعظم العقوق ترك الإنفاق عليهما، ولهذا كانت النفقة عليهما واجبة على الولد الموسر، ومن بعد الوالدين الأقربون على اختلاف طبقاتهم، الأقرب، فالأقرب، على حسب القرب والحاجة، فالإنفاق عليهم صدقة وصلة {واليتامى}؛ وهم الصغار الذين لا كاسب لهم فهم في مظنة الحاجة، لعدم قيامهم بمصالح أنفسهم وفقد الكاسب، فوصى الله بهم العباد رحمة منه بهم ولطفاً {والمساكين}؛ وهم أهل الحاجات وأرباب الضرورات الذين أسكنتهم الحاجة، فينفَق عليهم لدفع حاجاتهم وإغنائهم {وابن السبيل}؛ أي …","w":"السعدي","en":"Al-Sa'di: they ask you about spending, which covers both what is spent and on whom; He answers 'whatever you spend of good', little or much: the most deserving and first in line are those with the greatest right over you, the parents, to whom dutifulness is obligatory and disobedience forbidden. Among the greatest forms of dutifulness is spending on them, and among the greatest forms of disobedience is leaving them without it, so spending on them is obligatory for a well-off child. After parents come the relatives, nearest first, according to nearness and need, and spending on them is charity and keeping ties; then the orphans, the poor, and the wayfarer."},{"bk":"saadi","s":2,"ay":215,"x":"ولما خصص الله تعالى هؤلاء الأصناف لشدة الحاجة، عمم تعالى فقال:{وما تفعلوا من خير}؛ من صدقة على هؤلاء وغيرهم بل ومن جميع أنواع الطاعات والقربات لأنها تدخل في اسم الخير {فإن الله به عليم}؛ فيجازيكم عليه، ويحفظه لكم كلٌّ على حسب نيته وإخلاصه، وكثرة نفقته وقلتها، وشدة الحاجة إليها، وعظم وقعها ونفعها.","w":"السعدي","en":"Al-Sa'di: after specifying these groups because of their great need, He generalises: 'whatever you do of good' includes charity to them and others and every act of obedience and nearness, because all of it comes under the word good, 'and Allah is aware of it', so He will repay it and keep it for you according to your intention and sincerity, how much you spent, how great the need was and how great the benefit."}]},{"id":"aqaba","ch":"duafa","t":"اقتحام العقبة: فك الرقبة وإطعام اليتيم والمسكين","e":"وصف العقبة التي يقتحمها الإنسان: فك الرقبة وإطعام اليتيم والمسكين في يوم المجاعة.","ay":[[90,11,16]],"q":[{"bk":"saadi","s":90,"ay":11,"x":"ولكن هذا الإنسان لم يفعل ذلك؛ {فلا اقتحم العقبة}؛ أي: لم يقتحمْها ويعبُرْ عليها؛ لأنه متَّبع لهواه ، وهذه العقبة شديدةٌ عليه.","w":"السعدي","en":"Al-Sa'di: but this person did not do that: 'he did not attempt the steep path', meaning he did not climb it and cross it because he follows his desire, and this path is hard on him."},{"bk":"saadi","s":90,"ay":13,"x":"ثم فسَّر هذه العقبة بقوله: {فكُّ رقبةٍ}؛ أي: فكُّها من الرقِّ بعتقها أو مساعدتها على أداء كتابتها، ومن باب أولى فكاك الأسير المسلم عند الكفار، {أو إطعامٌ في يوم ذي مَسۡغَبَةٍ}؛ أي: مجاعةٍ شديدةٍ؛ بأن يطعم وقت الحاجة أشدَّ الناس حاجةً، {يتيماً ذا مَقۡرَبَةٍ}؛ أي: جامعاً بين كونه يتيماً وفقيراً ذا قرابة، {أو مسكيناً ذا مَتۡرَبَةٍ}؛ أي: قد لزق بالتراب من الحاجة والضَّرورة.","w":"السعدي","en":"Al-Sa'di: then He explains the steep path: 'freeing a neck', by releasing it from slavery or helping it pay its contract, and all the more so ransoming a Muslim prisoner held by unbelievers; 'or feeding on a day of severe hunger', feeding at a time of need those in the greatest need; 'an orphan of near relation', both orphan and poor and a relative; 'or a poor person in the dust', one pressed to the earth by need."}]},{"id":"yatim","ch":"duafa","t":"«فأما اليتيم فلا تقهر» و«كلا بل لا تكرمون اليتيم»","e":"النهي عن قهر اليتيم والأمر بإكرامه، وذمّ من لا يكرمه.","ay":[[93,9,10],[89,17,18]],"q":[{"bk":"saadi","s":93,"ay":10,"x":"ولهذا قال: {فأمَّا اليتيمَ فلا تَقۡهَرۡ}؛ أي: لا تُسِئْ معاملة اليتيم، ولا يَضِقْ صدرُك عليه، ولا تنهره، بل أكرمه، وأعطه ما تيسَّر، واصنع به كما تحبُّ أن يُصْنَعَ بولدك من بعدك، {وأمَّا السائلَ فلا تنهر}؛ أي: لا يصدر منك كلامٌ للسائل يقتضي ردَّه عن مطلوبه بنَهْرٍ وشراسةِ خلقٍ، بل أعطه ما تيسَّر عندك، أو ردَّه بمعروفٍ وإحسانٍ.","w":"السعدي","en":"Al-Sa'di: 'so as for the orphan, do not oppress him': do not mistreat the orphan, do not be short with him or rebuke him, but honour him, give him what you can and treat him as you would like your own child to be treated after you; 'and as for the one who asks, do not repel': do not say anything that would turn him away from his request harshly, but give him what you can or turn him down with kindness and good speech."},{"bk":"saadi","s":89,"ay":17,"x":"وأيضاً؛ فإنَّ وقوف همَّة العبد عند مراد نفسه فقط من ضعف الهمَّة، ولهذا لامَهُمُ الله على عدم اهتمامهم بأحوال الخلق المحتاجين، فقال:{كلاَّ بل لا تكرِمون اليتيمَ}: الذي فقد أباه وكاسبه واحتاج إلى جبر خاطره والإحسان إليه؛ فأنتُم لا تكرِمونه بل تهينونه، وهذا يدلُّ على عدم الرحمة في قلوبكم وعدم الرغبة في الخير، {ولا تحاضُّون على طعام المسكين}؛ أي: لا يحضُّ بعضكم بعضاً على إطعام المحاويج من الفقراء والمساكين ، وذلك لأجل الشحِّ على الدنيا ومحبَّتها الشديدة المتمكَّنة من القلوب.","w":"السعدي","en":"Al-Sa'di: a person whose concern stops at his own wants has weak resolve, so Allah blames them for not caring about the needy: 'No, but you do not honour the orphan' who lost his father and provider and needs comfort and kindness, but you do not honour him, you slight him, which shows no mercy in your hearts and no desire for good; 'and you do not urge one another to feed the poor', which is because of clinging to this world and loving it intensely."}]},{"id":"maun","ch":"duafa","t":"«يدع اليتيم ولا يحض على طعام المسكين»","e":"ذمّ الذي يدفع اليتيم ولا يحض على طعام المسكين.","ay":[[107,1,3]],"q":[{"bk":"saadi","s":107,"ay":2,"x":"{فذلك الذي يَدُعُّ اليتيمَ}؛ أي: يدفعه بعنفٍ وشدَّةٍ، ولا يرحمه؛ لقساوة قلبه، ولأنَّه لا يرجو ثواباً ولا يخاف عقاباً.","w":"السعدي","en":"Al-Sa'di: 'that is the one who repels the orphan' means he pushes him away with harshness and does not show mercy, because his heart is hard and he neither hopes for reward nor fears punishment."},{"bk":"saadi","s":107,"ay":2,"x":"وفي هذه السورة الحثُّ على إطعام اليتيم والمساكين، والتَّحضيض على ذلك، ومراعاة الصَّلاة، والمحافظة عليها، وعلى الإخلاص فيها، وفي سائر الأعمال ، والحثُّ على فعل المعروف، وبذل الأمور الخفيفة كعارية الإناء والدَّلو والكتاب ونحو ذلك؛ لأنَّ الله ذمَّ من لم يفعل ذلك.","w":"السعدي","en":"Al-Sa'di: in this surah is the urging to feed orphans and the poor, to keep the prayer with sincerity in it and in all deeds, to do good and to give small items such as lending a pot, a bucket or a book, because Allah blamed whoever does not do this."}]},{"id":"qurba","ch":"duafa","t":"«وآت ذا القربى حقه والمسكين وابن السبيل»","e":"الأمر بإيتاء ذي القربى والمسكين وابن السبيل حقوقهم.","ay":[[17,26,26],[30,38,38]],"q":[{"bk":"saadi","s":17,"ay":26,"x":"يقول تعالى: {وآت ذا القُربى حقَّه}: من البرِّ والإكرام الواجب والمسنون، وذلك الحقُّ يتفاوت بتفاوت الأحوال والأقارب والحاجة وعدمها والأزمنة، {والمسكينَ}: آته حقَّه من الزَّكاة ومن غيرها؛ لتزول مسكنتُه، {وابنَ السبيل}: وهو الغريب المنقطع به عن بلده، فيُعْطى الجميع من المال، على وجهٍ لا يضرُّ المعطي، ولا يكون زائداً على المقدار اللائق؛ فإنَّ ذلك تبذيرٌ، قد نهى الله عنه وأخبر: إنَّ المبذِّرين {إخوانُ الشياطين}: لأنَّ الشيطان لا يدعو إلاَّ إلى كلِّ خَصلة ذميمةٍ، فيدعو الإنسان إلى البخل والإمساك؛ فإذا عصاه؛ دعاه إلى الإسراف والتبذير، والله تعالى إنَّما يأمُرُ بأعدل الأمور وأقسطِها، ويمدحُ عليه؛ كما في قوله عن عباد الرحمن الأبرار:{والذين إذا أنفقوا لم يُسۡرِفوا ولم يَقۡتُروا وكان بين ذلك قَواماً}.","w":"السعدي","en":"Al-Sa'di: 'give the relative his right': of birr and honour, obligatory and recommended, a right that varies with circumstances, the relatives, need or its absence and the times; 'and the poor': give him his due from zakat and otherwise, so his poverty goes; 'and the wayfarer': the stranger cut off from his land. All are to be given in a way that does not harm the giver and does not exceed what is fitting, for that is wasting, which Allah forbade and called the wasteful 'brothers of the devils'. The devil calls only to blameworthy traits, first to miserliness, then if refused, to extravagance, while Allah commands the most just course, as in His praise of the abrar among the servants of the Merciful: when they spend they are neither extravagant nor stingy, but between the two."},{"bk":"saadi","s":30,"ay":38,"x":"أي: فأعطِ القريب منك ـ على حسب قربِهِ وحاجتِهِ ـ حقَّه الذي أوجبه الشارع أو حضَّ عليه من النفقةِ الواجبة والصدقةِ والهديَّة والبرِّ والسلام والإكرام والعفوِ عن زلَّته والمسامحة عن هفوتِهِ، وكذلك آتِ المسكين الذي أسْكَنَهُ الفقرُ والحاجةُ ما تُزيل به حاجَتَه وتدفعُ به ضرورتَه من إطعامه وسقيه وكسوتِهِ.","w":"السعدي","en":"Al-Sa'di: give your relative his right, according to his nearness and need, whatever the Law made obligatory or encouraged of required spending, charity, gifts, kindness (birr), greeting and honour, forgiving his slips and overlooking his mistakes; and give the poor person who is held down by need what removes his need and meets his necessity of food, drink and clothing."}]},{"id":"tawun","ch":"tawun","t":"«وتعاونوا على البر والتقوى»","e":"الأمر بالتعاون على البر والتقوى والنهي عن التعاون على الإثم والعدوان.","ay":[[5,2,2]],"q":[{"bk":"saadi","s":5,"ay":2,"x":"{وتعاوَنوا على البِرِّ والتَّقوى}؛ أي: ليُعِنْ بعضكم بعضاً على البرِّ، وهو اسم جامع لكل ما يحبُّه الله ويرضاه من الأعمال الظاهرة والباطنة من حقوق الله وحقوق الآدميين، والتقوى في هذا الموضع اسم جامع لِتَرْكِ كلِّ ما يكرهه الله ورسوله من الأعمال الظاهرة والباطنة، وكل خصلة من خصال الخير المأمور بفعلها، أو خصلةٍ من خصال الشرِّ المأمور بتركها؛ فإن العبد مأمورٌ بفعلها بنفسه وبمعاونة غيره من إخوانه المؤمنين عليها بكلِّ قول يَبعث عليها وينشِّطُ لها وبكل فعل كذلك.","w":"السعدي","en":"Al-Sa'di: 'Cooperate in birr and taqwa' means help one another in birr, a comprehensive word for everything Allah loves and is pleased with, outward and inward, of the rights of Allah and the rights of people; taqwa here is a comprehensive word for leaving everything Allah and His Messenger dislike, outward and inward. Every good trait commanded, or evil trait commanded to be left, a servant is commanded to carry out himself and with the help of his believing brothers, by every word and deed that urges and energises it."},{"bk":"ibnkathir","s":5,"ay":2,"x":"وَقَوْلُهُ: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإثْمِ وَالْعُدْوَانِ﴾ يَأْمُرُ تَعَالَى عِبَادَهُ الْمُؤْمِنِينَ بِالْمُعَاوَنَةِ عَلَى فِعْلِ الْخَيْرَاتِ، وَهُوَ الْبَرُّ، وَتَرْكِ الْمُنْكِرَاتِ وَهُوَ التَّقْوَى، وَيَنْهَاهُمْ عَنِ التناصر على الباطل.","w":"ابن كثير","en":"Ibn Kathir: 'cooperate in birr and taqwa and do not cooperate in sin and aggression': Allah commands His believing servants to help one another do good, which is birr, and to leave evils, which is taqwa, and forbids them to support one another in falsehood."}]},{"id":"islah","ch":"tawun","t":"«أن تبروا وتتقوا وتصلحوا بين الناس»","e":"النهي عن جعل اليمين مانعاً من البر والإصلاح، وبيان ما فيه خير من الحديث.","ay":[[2,224,224],[4,114,114]],"q":[{"bk":"saadi","s":2,"ay":224,"x":"وكان الله تعالى قد أمر بحفظ الأيمان وكان مقتضى ذلك حفظها في كل شيء، ولكن الله تعالى استثنى من ذلك إذا كان البر باليمين يتضمن ترك ما هو أحب إليه فنهى عباده أن يجعلوا أيمانهم عرضة أي مانعة وحائلة عن أن يبروا أي يفعلوا خيراً ويتقوا شرًّا ويصلحوا بين الناس …","w":"السعدي","en":"Al-Sa'di: Allah had commanded keeping oaths, which would mean keeping them in everything, but He made an exception where keeping the oath would mean leaving what is better, so He forbade His servants to make their oaths 'an obstacle', a barrier that keeps them from being dutiful (birr), meaning doing good, fearing Allah and making peace between people."},{"bk":"saadi","s":4,"ay":114,"x":"ولهذا قال:{ومن يفعل ذلك ابتغاءَ مرضاةِ الله فسوف نؤتيه أجراً عظيماً}؛ فلهذا ينبغي للعبد أن يقصدَ وجه الله تعالى ويُخْلِصَ العمل لله في كلِّ وقت وفي كلِّ جزء من أجزاء الخير؛ ليحصلَ له بذلك الأجر العظيم، وليتعوَّد الإخلاص، فيكون من المخلصين. وليتمَّ له الأجر، سواءٌ تمَّ مقصودُه أم لا؛ لأنَّ النيَّة حصلت، واقترن بها ما يمكنُ من العمل.","w":"السعدي","en":"Al-Sa'di: 'whoever does that seeking Allah's pleasure, We will give him a great reward' - so a servant should aim at Allah's face and be sincere in every moment and every part of good, to gain that great reward and to get used to sincerity, and so that his reward is complete whether or not his aim is achieved, since the intention was there and was joined by what deed was possible."}]},{"id":"mumtahana","ch":"tawun","t":"«أن تبروهم وتقسطوا إليهم»","e":"بيان أن البر والقسط جائزان مع من لم يقاتل المسلمين في الدين.","ay":[[60,8,8]],"q":[{"bk":"saadi","s":60,"ay":8,"x":"ولمَّا نزلت هذه الآيات الكريمات المهيِّجةُ على عداوة الكافرين؛ وقعتْ من المؤمنين كلَّ موقع، وقاموا بها أتمَّ القيام، وتَأثَّموا من صِلَةِ بعض أقاربهم المشركين، وظنُّوا أنَّ ذلك داخل فيما نهى الله عنه، فأخبرهم الله أن ذلك لا يدخُلُ في المحرم، فقال:{لا ينهاكُمُ الله عن الذين لم يقاتِلوكم في الدِّينِ ولم يُخۡرِجُوكم من دياركُم أن تَبَرُّوهم وتُقۡسِطوا إليهم إنَّ الله يحبُّ المقسِطينَ}؛ أي: لا ينهاكم الله عن البرِّ والصِّلة والمكافأة بالمعروف والقسطِ للمشركين من أقاربكم وغيرهم؛ حيث كانوا بحالٍ لم ينتصبوا لقتالكم في الدين والإخراج من دياركم؛ فليس عليكم جناحٌ أن تَصِلوهم؛ فإنَّ صِلَتَهم في هذه الحالة لا محذورَ فيها ولا تَبِعَةَ ؛ كما قال تعالى في الأبوين الكافرين إذا كان ولدهما مسلماً …","w":"السعدي","en":"Al-Sa'di: when the verses that stir up enmity toward the unbelievers came down, the believers took them to heart and carried them out fully, and some felt guilty about keeping ties with their polytheist relatives, thinking that this fell under what Allah forbade. So Allah told them it is not forbidden: 'Allah does not forbid you from those who did not fight you over religion or expel you from your homes, that you deal kindly with them and act justly toward them; Allah loves the just'. That is, He does not forbid birr, keeping ties, repaying kindness and fairness toward polytheists, relatives or not, as long as they have not set themselves up to fight you over religion and expel you, so there is no blame in keeping ties with them in that case, as He said about unbelieving parents with a Muslim child."},{"bk":"ibnkathir","s":60,"ay":8,"x":"وَقَوْلُهُ تَعَالَى: ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ﴾ أَيْ لَا يَنْهَاكُمْ عَنِ الْإِحْسَانِ إِلَى الْكَفَرَةِ الَّذِينَ لَا يُقَاتِلُونَكُمْ فِي الدِّينِ، كَالنِّسَاءِ وَالضَّعَفَةِ مِنْهُمْ، ﴿أَنْ تَبَرُّوهُمْ﴾ أَيْ: تُحْسِنُوا إِلَيْهِمْ ﴿وَتُقْسِطُوا إِلَيْهِمْ﴾ أَيْ: تَعْدِلُوا ﴿إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ﴾ .","w":"ابن كثير","en":"Ibn Kathir: 'Allah does not forbid you from those who did not fight you over religion or expel you from your homes' means He does not forbid you to be good to unbelievers who do not fight you over religion, such as their women and weak ones, 'that you deal kindly with them' meaning be good to them, 'and act justly toward them' meaning be fair; 'Allah loves the just'."}]},{"id":"najwa","ch":"tawun","t":"«وتناجوا بالبر والتقوى»","e":"الأمر بالتناجي بالبر والتقوى لا بالإثم والعدوان.","ay":[[58,9,9]],"q":[{"bk":"saadi","s":58,"ay":9,"x":"النَّجْوى هي التناجي بين اثنين فأكثر، وقد تكون في الخير وتكونُ في الشرِّ، فأمر الله المؤمنين أنْ يَتَناجَوْا بالبرِّ، وهو اسمٌ جامعٌ لكلِّ خيرٍ وطاعةٍ وقيام بحقِّ الله وحقِّ عباده ، والتَّقوى، وهي هنا اسمٌ جامعٌ لترك جميع المحارم والمآثم؛ فالمؤمن يمتثل هذا الأمر الإلهيَّ؛ فلا تجده مناجياً ومتحدثاً إلاَّ بما يقرِّبه إلى الله ويباعده من سخطه …","w":"السعدي","en":"Al-Sa'di: najwa is private talk between two or more, and it may be for good or for evil. Allah commanded the believers to confer in birr, a comprehensive word for every good, act of obedience and fulfilling of Allah's right and His servants' rights, and in taqwa, here a comprehensive word for leaving all that is forbidden and sinful. The believer follows this command, so you find him conferring only in what brings him near to Allah and away from His anger."}]},{"id":"adl","ch":"tawun","t":"«إن الله يأمر بالعدل والإحسان وإيتاء ذي القربى»","e":"الأمر بالعدل والإحسان وإيتاء ذي القربى والنهي عن الفحشاء والمنكر والبغي.","ay":[[16,90,90]],"q":[{"bk":"saadi","s":16,"ay":90,"x":"والعدل: هو ما فَرَضَه الله عليهم في كتابه وعلى لسان رسوله وأمرهم بسلوكه، ومن العدل في المعاملات أن تعامِلَهم في عقود البيع والشراء وسائر المعاوضات بإيفاء جميع ما عليك؛ فلا تبخسُ لهم حقًّا، ولا تغشُّهم ولا تخدعُهم وتظلِمُهم؛ فالعدل واجبٌ، والإحسان فضيلةٌ مستحبٌّ، وذلك كنفع الناس بالمال والبدن والعلم وغير ذلك من أنواع النفع، حتى يدخلَ فيه الإحسان إلى الحيوان البهيم المأكول وغيره، وخصَّ الله إيتاء ذي القُربى وإن كان داخلاً في العموم؛ لتأكُّد حقِّهم وتعيُّن صلتهم وبرِّهم والحرص على ذلك، ويدخل في ذلك جميع الأقارب؛ قريبهم وبعيدهم، لكن كلُّ مَن كان أقربَ كان أحقَّ بالبرِّ.","w":"السعدي","en":"Al-Sa'di: justice is what Allah made obligatory in His Book and on the tongue of His Messenger, and part of justice in dealings is to give everything you owe in sales, purchases and exchanges, not cheating or deceiving or wronging anyone. Justice is obligatory, ihsan is a recommended virtue, like benefiting people with money, effort, knowledge and other kinds of benefit, even doing good to animals. Allah singled out giving relatives, though it falls under the general rule, because of the strength of their right and the need to keep ties and be dutiful (birr) to them."}]},{"id":"kas","ch":"abrar","t":"«إن الأبرار يشربون من كأس»","e":"وصف شراب الأبرار في الجنة وأعمالهم التي أوصلتهم إليها.","ay":[[76,5,12]],"q":[{"bk":"saadi","s":76,"ay":5,"x":"وأمَّا {الأبرار}، وهم الذين بَرَّتْ قلوبُهم بما فيها من معرفة الله ومحبَّته والأخلاق الجميلة؛ فبرَّت أعمالُهم ، واستعملوها بأعمال البرِّ، فأخبر أنَّهم {يشربون من كأسٍ}؛ أي: شرابٍ لذيذٍ من خمرٍ [قد] مُزِجَ بكافورٍ؛ أي: خلط به ليبرِّده ويكسر حدَّته، وهذا الكافور في غاية اللَّذَّة، قد سلم من كلِّ مكدِّرٍ ومنغِّص موجودٍ في كافور الدُّنيا …","w":"السعدي","en":"Al-Sa'di: as for the abrar, they are those whose hearts were righteous through knowing and loving Allah and having beautiful character, so their deeds were righteous and they used them in works of birr. He tells us that 'they drink from a cup': a delicious drink of wine mixed with camphor, to cool it and soften its sharpness, a camphor perfectly pleasant and free from every spoiler present in the camphor of this world, since worldly flaws are absent from the things Allah named in Paradise …"},{"bk":"saadi","s":76,"ay":8,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا، {إنا نخاف من ربِّنا يوماً عبوساً}؛ أي: شديد الجهمة والشرِّ، {قمطريراً}؛ أي: ضنكاً ضيقاً.","w":"السعدي","en":"Al-Sa'di: 'they feed food despite their love for it' means while they love wealth and food, they put love of Allah before love of themselves and choose those most in need to feed, 'the poor, the orphan and the captive', seeking Allah's face by their spending, and saying in their hearts 'we feed you only for Allah's face; we want from you neither reward nor thanks', neither material return nor words of praise, 'we fear from our Lord a frowning, distressful day'."}]},{"id":"naim","ch":"abrar","t":"«إن الأبرار لفي نعيم»","e":"نعيم الأبرار في الآخرة في مقابل جحيم الفجّار.","ay":[[82,13,16],[83,22,28]],"q":[{"bk":"saadi","s":82,"ay":13,"x":"المراد بالأبرار هم: القائمون بحقوق الله وحقوق عباده، الملازمون للبرِّ في أعمال القلوب وأعمال الجوارح؛ فهؤلاء جزاؤهم النعيم في القلب والرُّوح والبدن في دار الدُّنيا وفي دار البرزخ وفي دار القرار، {وإنَّ الفجَّارَ}: الذين قصَّروا في حقوق الله وحقوق عباده، الذين فَجَرَتْ قلوبُهم ففَجَرَتْ أعمالُهم، {لفي جحيمٍ}؛ أي: عذابٍ أليمٍ في دار الدُّنيا ودار البرزخ وفي دار القرار، {يَصۡلَوۡنها}: ويعذَّبون بها أشدَّ العذاب {يومَ الدِّينِ}؛ أي: يوم الجزاء على الأعمال، {وما هم عنها بغائبينَ}؛ أي: بل هم ملازمون لها لا يخرُجون منها …","w":"السعدي","en":"Al-Sa'di: the abrar are those who fulfil Allah's rights and His servants' rights and keep to birr in deeds of the heart and deeds of the limbs; their reward is delight of the heart, soul and body, in this world, in the barzakh and in the final abode. 'And the wicked', who fell short of Allah's rights and His servants' rights, whose hearts were corrupt so their deeds were corrupt, 'will be in Hell', a painful punishment in this world, the barzakh and the final abode, 'they will burn in it on the Day of Judgement', the day of repayment for deeds, 'and they will not be absent from it', never leaving it …"},{"bk":"saadi","s":83,"ay":22,"x":"فلمَّا ذَكَرَ كتابَهم؛ ذَكَرَ أنَّهم في نعيم، وهو اسمٌ جامعٌ لنعيم القلب والرُّوح والبدن.","w":"السعدي","en":"Al-Sa'di: after mentioning their record, He mentions that they are in delight, which is a comprehensive word for the delight of the heart, the soul and the body."}]},{"id":"illiyin","ch":"abrar","t":"«كتاب الأبرار لفي عليين»","e":"كتاب الأبرار في عليين يشهده المقربون.","ay":[[83,18,21]],"q":[{"bk":"saadi","s":83,"ay":18,"x":"لما ذكر أنَّ كتاب الفجَّار في أسفل الأمكنة وأضيقها؛ ذكر أنَّ كتاب الأبرار في أعلاها وأوسعها وأفسحها، وأنَّ كتابهم المرقوم {يشهدُهُ المقرَّبون}: من الملائكة الكرام وأرواح الأنبياء والصِّدِّيقين والشهداء ، وينوِّه الله بذكرهم في الملأ الأعلى. وعليُّون: اسم لأعلى الجنة.","w":"السعدي","en":"Al-Sa'di: after saying that the record of the wicked is in the lowest and narrowest of places, He says the record of the abrar is in the highest, widest and roomiest, and their inscribed record 'is witnessed by those brought near', the noble angels and the spirits of the prophets, the truthful and the martyrs, and Allah praises them in the highest company. Illiyun is the name of the highest part of Paradise."}]},{"id":"tawaffa","ch":"abrar","t":"«وتوفنا مع الأبرار» و«وما عند الله خير للأبرار»","e":"دعاء المؤمنين أن يُتوفوا مع الأبرار، وبيان أن ما عند الله خير لهم.","ay":[[3,193,193],[3,198,198]],"q":[{"bk":"saadi","s":3,"ay":193,"x":"والذي مَنَّ عليهم بالإيمان سيمنُّ عليهم بالأمان التام، {وتوفنا مع الأبرار}، يتضمن هذا الدعاء التوفيق لفعل الخير وترك الشر الذي به يكون العبد من الأبرار والاستمرار عليه والثبات إلى الممات.","w":"السعدي","en":"Al-Sa'di: the One who favoured them with faith will favour them with complete safety. 'And take us in death with the abrar' includes the prayer for success in doing good and leaving evil, by which a servant becomes one of the abrar, and for continuing and being firm in it until death."},{"bk":"saadi","s":3,"ay":198,"x":"وأما المتقون لربهم المؤمنون به فمع ما يحصل لهم من عز الدنيا ونعيمها {لهم جنات تجري من تحتها الأنهار خالدين فيها}؛ فلو قدر أنهم في دار الدنيا قد حصل لهم كلُّ بؤسٍ وشدَّةٍ وعَناءٍ ومشقةٍ، لكان هذا بالنسبة إلى النعيم المقيم والعيش السليم والسرور والحبور والبهجة نزراً يسيراً ومنحة في صورة محنة، ولهذا قال تعالى:{وما عند الله خير للأبرار} وهم الذين برّت قلوبهم فبرّت أقوالهم وأفعالهم فأثابهم البَرُّ الرحيم من بِرِّه أجراً عظيماً وعطاءً جسيماً وفوزاً دائماً.","w":"السعدي","en":"Al-Sa'di: as for those who fear their Lord and believe in Him, along with the honour and comfort they get in this world, 'for them are gardens beneath which rivers flow, abiding in them'. Even if every hardship, distress and toil had come to them in this world, it would be little next to lasting delight, a safe life and joy, a gift disguised as a trial; so Allah said 'what is with Allah is better for the abrar', those whose hearts were righteous so their words and deeds were righteous, and the Kind, the Merciful rewarded them from His kindness with a great reward, a large gift and lasting success."}]},{"id":"safara","ch":"abrar","t":"«بأيدي سفرة كرام بررة»","e":"وصف الملائكة حَمَلة الصحف بأنهم كرام بررة.","ay":[[80,11,16]],"q":[{"bk":"saadi","s":80,"ay":15,"x":"{مرفوعةٍ}: القدر والرتبة، {مُطَهَّرَةٍ}: من الآفات وعن أن تنالها أيدي الشياطين أو يسترقوها، بل هي {بأيدي سفرةٍ}: وهم الملائكة الذين هم سفراء بين الله وبين عباده، {كرامٍ}؛ أي: كثيري الخير والبركة، {بَرَرةٍ}: قلوبهم وأعمالهم.","w":"السعدي","en":"Al-Sa'di: 'raised' in rank and standing, 'purified' of flaws and from the hands of devils who might touch or steal them, but they are 'in the hands of scribes', the angels, who are envoys between Allah and His servants, 'noble', of much good and blessing, 'righteous' (bararah) in their hearts and their deeds."},{"bk":"saadi","s":80,"ay":16,"x":"وذلك كلُّه حفظٌ من الله لكتابه؛ أن جعل السفراء فيه إلى الرسل الملائكة الكرام الأقوياء الأتقياء، ولم يجعلْ للشياطين عليه سبيلاً، وهذا مما يوجب الإيمان به وتلقِّيه بالقَبول.","w":"السعدي","en":"Al-Sa'di: all of that is Allah's protection of His Book, that He made the envoys who carry it to the messengers noble, strong, godfearing angels, and gave devils no way to it, which calls for believing in it and receiving it with acceptance."}]}],"ay":{"50":"۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","195":"۞ يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","221":"يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","230":"وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ","384":"لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","485":"رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ","490":"لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ","528":"۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","606":"۞ لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","670":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","1990":"۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","2051":"۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا","2052":"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا","2054":"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا","2261":"يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا","2262":"وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا","2263":"وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا","2279":"قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا","2280":"وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا","2281":"وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا","2282":"وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا","3446":"فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرٞ لِّلَّذِينَ يُرِيدُونَ وَجۡهَ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","3482":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنٖ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ","3483":"وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفٗاۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","4524":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ","4760":"قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ","4761":"فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ","4762":"إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ","5112":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَنَٰجَيۡتُمۡ فَلَا تَتَنَٰجَوۡاْ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَمَعۡصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوۡاْ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ","5157":"لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","5595":"إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا","5596":"عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا","5597":"يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5600":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","5601":"فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا","5602":"وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا","5768":"كـَلَّآ إِنَّهَا تَذۡكِرَةٞ","5769":"فَمَن شَآءَ ذَكَرَهُۥ","5770":"فِي صُحُفٖ مُّكَرَّمَةٖ","5771":"مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ","5772":"بِأَيۡدِي سَفَرَةٖ","5773":"كِرَامِۭ بَرَرَةٖ","5841":"إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ","5842":"وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ","5843":"يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ","5844":"وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ","5865":"كـَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ","5866":"وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ","5867":"كِتَٰبٞ مَّرۡقُومٞ","5868":"يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ","5869":"إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ","5870":"عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","5871":"تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ","5872":"يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ","5873":"خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ","5874":"وَمِزَاجُهُۥ مِن تَسۡنِيمٍ","5875":"عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ","6009":"كـَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","6010":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","6033":"فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","6034":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","6035":"فَكُّ رَقَبَةٍ","6036":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","6037":"يَتِيمٗا ذَا مَقۡرَبَةٍ","6038":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","6087":"فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ","6088":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ","6197":"أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","6198":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","6199":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ"},"nay":73,"nq":49};
